def check_m(m):
    if m % 2 == 0:
        return False

    # Define the coloring
    edges = []
    for i in range(m):
        for j in range(i + 1, m):
            edges.append(((i, j), (i + j) % m))

    # Count colors
    color_counts = {}
    for _, color in edges:
        color_counts[color] = color_counts.get(color, 0) + 1

    # Each color must appear (m-1)/2 times
    expected_count = (m - 1) // 2
    for color in range(m):
        if color_counts.get(color, 0) != expected_count:
            return False

    # Collect all triangles and their color triples
    triangles = []
    for i in range(m):
        for j in range(i + 1, m):
            for k in range(j + 1, m):
                c1 = (i + j) % m
                c2 = (j + k) % m
                c3 = (k + i) % m

                # Each triangle must have 3 distinct colors
                if len({c1, c2, c3}) != 3:
                    return False

                triangles.append(tuple(sorted((c1, c2, c3))))

    # Each triple of colors must appear exactly once
    triples = set()
    for t in triangles:
        if t in triples:
            return False
        triples.add(t)

    return len(triples) == (m * (m - 1) * (m - 2)) // 6

